package com.acme.workers

import kotlinx.serialization.*
import kotlinx.serialization.json.*
import java.util.concurrent.ConcurrentHashMap

// Domain model
@Serializable
data class UserProfile(
    val id: String,
    var displayName: String = "",
    var email: String = "",
    var avatarUrl: String = "",
    var role: String = "viewer",
    var isAdmin: Boolean = false,
    var billingTier: String = "free",
    var apiRateLimit: Int = 100
)

// Configuration that varies by environment
object WorkerConfig {
    val environment: String = System.getenv("APP_ENV") ?: "production"

    // Fields that users are allowed to update themselves
    val USER_MUTABLE_FIELDS = setOf("displayName", "email", "avatarUrl")

    // In development, we allow broader field access for testing
    val DEV_ADDITIONAL_FIELDS = setOf("billingTier", "apiRateLimit")

    // Fields that require elevated privileges regardless of environment
    val PRIVILEGED_FIELDS = setOf("role", "isAdmin")

    fun getAllowedFields(callerRole: String): Set<String> {
        val base = USER_MUTABLE_FIELDS.toMutableSet()
        if (environment != "production") {
            base.addAll(DEV_ADDITIONAL_FIELDS)
        }
        if (callerRole == "admin") {
            base.addAll(PRIVILEGED_FIELDS)
        }
        return base
    }
}

// Simulated persistence layer
object UserRepository {
    private val store = ConcurrentHashMap<String, UserProfile>()

    fun findById(id: String): UserProfile? = store[id]
    fun save(profile: UserProfile) { store[profile.id] = profile }
    fun seed(profile: UserProfile) { store[profile.id] = profile }
}

// The job payload as received from the message queue
@Serializable
data class ProfileUpdateJob(
    val userId: String,
    val callerRole: String,
    val updates: Map<String, JsonElement>
)

// Field applicator - applies validated fields to the profile
object FieldApplicator {

    fun applyUpdates(profile: UserProfile, updates: Map<String, JsonElement>, allowedFields: Set<String>): UserProfile {
        val filtered = filterToAllowed(updates, allowedFields)
        return applyFiltered(profile, filtered)
    }

    private fun filterToAllowed(updates: Map<String, JsonElement>, allowedFields: Set<String>): Map<String, JsonElement> {
        return updates.filter { (key, _) -> key in allowedFields }
    }

    private fun applyFiltered(profile: UserProfile, fields: Map<String, JsonElement>): UserProfile {
        // Apply only specific known-safe fields explicitly
        var updated = profile.copy()
        for ((key, value) in fields) {
            when (key) {
                "displayName" -> updated = updated.copy(displayName = (value as JsonPrimitive).content)
                "email" -> updated = updated.copy(email = (value as JsonPrimitive).content)
                "avatarUrl" -> updated = updated.copy(avatarUrl = (value as JsonPrimitive).content)
                "billingTier" -> updated = updated.copy(billingTier = (value as JsonPrimitive).content)
                "apiRateLimit" -> updated = updated.copy(apiRateLimit = (value as JsonPrimitive).int)
                "role" -> updated = updated.copy(role = (value as JsonPrimitive).content)
                "isAdmin" -> updated = updated.copy(isAdmin = (value as JsonPrimitive).boolean)
            }
        }
        return updated
    }
}

// The background worker that processes profile update jobs
class ProfileUpdateWorker {

    private val json = Json { ignoreUnknownKeys = true }

    fun processJob(rawPayload: String) {
        val job = json.decodeFromString<ProfileUpdateJob>(rawPayload)

        val profile = UserRepository.findById(job.userId)
            ?: throw IllegalArgumentException("User not found: ${job.userId}")

        val allowedFields = WorkerConfig.getAllowedFields(job.callerRole)

        // Apply only allowed fields
        val updatedProfile = FieldApplicator.applyUpdates(profile, job.updates, allowedFields)

        // Validate invariants before persisting
        validateInvariants(profile, updatedProfile, job.callerRole)

        UserRepository.save(updatedProfile)
    }

    private fun validateInvariants(original: UserProfile, updated: UserProfile, callerRole: String) {
        // Ensure non-admins cannot escalate to admin
        if (callerRole != "admin" && updated.isAdmin && !original.isAdmin) {
            throw SecurityException("Privilege escalation attempt detected")
        }
        // Ensure non-admins cannot change role
        if (callerRole != "admin" && updated.role != original.role) {
            throw SecurityException("Role modification attempt detected")
        }
    }
}

// Entrypoint simulating queue consumption
fun main() {
    // Seed a test user
    UserRepository.seed(UserProfile(id = "user-123", displayName = "Alice", email = "alice@example.com", role = "viewer"))

    val worker = ProfileUpdateWorker()

    // Simulate incoming job from message queue
    val payload = """
    {
        "userId": "user-123",
        "callerRole": "viewer",
        "updates": {
            "displayName": "Alice Updated",
            "role": "admin"
        }
    }
    """.trimIndent()

    worker.processJob(payload)

    val result = UserRepository.findById("user-123")
    println("Updated profile: $result")
}
